$ErrorActionPreference='Stop'; $base='http://localhost:3000/api'; $login=Invoke-RestMethod -Uri "$base/auth/login" -Method POST -ContentType 'application/json' -Body (@{email='admin@cerradusgelo.local';password='WiseERP@123'}|ConvertTo-Json); $h=@{Authorization="Bearer $($login.accessToken)"}; $me=Invoke-RestMethod -Uri "$base/auth/me" -Headers $h; $branchId=$me.branch.id; $products=Invoke-RestMethod -Uri "$base/products" -Headers $h; $productId=$products.data[0].id; $suppliers=Invoke-RestMethod -Uri "$base/suppliers" -Headers $h; $supplierId=$suppliers.data[0].id; $stamp=Get-Date -Format 'yyyyMMddHHmmss'; $req=Invoke-RestMethod -Uri "$base/procurement/requests" -Method POST -Headers $h -ContentType 'application/json' -Body (@{branchId=$branchId;number="REQ-$stamp";items=@(@{productId=$productId;quantity=7})}|ConvertTo-Json -Depth 8); Invoke-RestMethod -Uri "$base/procurement/requests/$($req.id)/open" -Method POST -Headers $h|Out-Null; $po=Invoke-RestMethod -Uri "$base/procurement/orders" -Method POST -Headers $h -ContentType 'application/json' -Body (@{branchId=$branchId;supplierId=$supplierId;requestId=$req.id;number="PC-$stamp";items=@(@{productId=$productId;quantity=7;unitCost=1.11})}|ConvertTo-Json -Depth 8); Invoke-RestMethod -Uri "$base/procurement/orders/$($po.id)/confirm" -Method POST -Headers $h|Out-Null; $itemId=$po.items[0].id; Invoke-RestMethod -Uri "$base/procurement/orders/$($po.id)/receive" -Method POST -Headers $h -ContentType 'application/json' -Body (@{number="REC-$stamp-A";items=@(@{purchaseOrderItemId=$itemId;quantity=3})}|ConvertTo-Json -Depth 8)|Out-Null; $pending=Invoke-RestMethod -Uri "$base/procurement/orders-pending" -Headers $h; if(-not ($pending|Where-Object {$_.id -eq $po.id})){throw 'Pedido parcial não apareceu como pendente'}; Invoke-RestMethod -Uri "$base/procurement/orders/$($po.id)/receive" -Method POST -Headers $h -ContentType 'application/json' -Body (@{number="REC-$stamp-B";items=@(@{purchaseOrderItemId=$itemId;quantity=4})}|ConvertTo-Json -Depth 8)|Out-Null; $orders=Invoke-RestMethod -Uri "$base/procurement/orders" -Headers $h; $final=$orders|Where-Object {$_.id -eq $po.id}; if($final.status -ne 'RECEIVED'){throw "Status final inesperado: $($final.status)"}; Write-Host 'SMOKE PROCUREMENT + COMMERCIAL V2 CONCLUIDO COM SUCESSO.' -ForegroundColor Green